var root = protobuf.parse(proto, { keepCase: true }).root;
window.mesega = root.lookupType("Data");
var compressed = root.lookupType("uncompressedData");
function decodeMobileData(data) {
    /*
     * Decode exactly what was received.
     * Never hide a malformed packet by
     * deleting bytes from its tail.
     */
    return window.mesega.decode(data);
}

function encodeProtoVarint(value) {
    var number = Number(value);

    if (
        !Number.isSafeInteger(number) ||
        number < 0
    ) {
        throw new RangeError(
            'Invalid protobuf varint value: ' +
            value
        );
    }

    var bytes = [];

    do {
        var byte = number % 128;

        number =
            Math.floor(number / 128);

        if (number > 0) {
            byte |= 0x80;
        }

        bytes.push(byte);
    } while (number > 0);

    return bytes;
}

function ReqPing() {
    if (
        !legendmod.integrity ||
        !window.core ||
        typeof window.core
            .proxyMobileData !==
            'function'
    ) {
        return;
    }

    var pingId =
        Math.floor(
            Math.random() *
            0x7fffffff
        );

    var previousRoundtrip =
        Math.floor(
            Math.random() *
            0x7fffffff
        );

    var pingPayload = [8]
        .concat(
            encodeProtoVarint(
                previousRoundtrip
            )
        )
        .concat([16])
        .concat(
            encodeProtoVarint(
                pingId
            )
        );

    var uncompressedPayload =
        [8, 30, 242, 1]
            .concat(
                encodeProtoVarint(
                    pingPayload.length
                )
            )
            .concat(pingPayload);

    var packet = [8, 1, 18]
        .concat(
            encodeProtoVarint(
                uncompressedPayload
                    .length
            )
        )
        .concat(
            uncompressedPayload
        );

    window.agarpingstarted =
        Date.now();

    window.core.proxyMobileData(
        new Uint8Array(packet)
    );
}


