        //
        feed() {
            if (window.core && window.core.eject) {
                window.core.eject();
            }
        },
        macroFeedPerm(on) {
            if (on) {
                if (this.feedIntervalPerm) {
                    clearInterval(this.feedIntervalPerm);
                    this.feedIntervalPerm = null
                    return;
                }
                var app = this;
                this.feed();
                this.feedIntervalPerm = setInterval(function () {
                    app.feed();
                }, defaultmapsettings.macroFeeding);
            }
        },
        macrobotFeed(on) {
            if (on) {
                if (this.macrobotFeedActive) {
                    return;
                }

                this.macrobotFeedActive = true;

                var app = this;
                var lastFeedTime = 0;

                this.Botseject();

                function loop(now) {
                    if (!app.macrobotFeedActive) {
                        app.macrobotFeedFrame = null;
                        return;
                    }

                    var delay =
                        Number(defaultmapsettings.macroFeeding) || 10;

                    if (delay < 1) {
                        delay = 1;
                    }

                    if (now - lastFeedTime >= delay) {
                        lastFeedTime = now;
                        app.Botseject();
                    }

                    app.macrobotFeedFrame =
                        window.requestAnimationFrame(loop);
                }

                this.macrobotFeedFrame =
                    window.requestAnimationFrame(loop);
            } else {
                this.macrobotFeedActive = false;

                if (this.macrobotFeedFrame != null) {
                    window.cancelAnimationFrame(
                        this.macrobotFeedFrame
                    );
                    this.macrobotFeedFrame = null;
                }

                if (this.feedInterval) {
                    clearInterval(this.feedInterval);
                    this.feedInterval = null;
                }
            }
        },
        macroFeed(on) {
            if (on) {
                if (this.macroFeedActive) {
                    return;
                }

                this.macroFeedActive = true;

                var app = this;
                var lastFeedTime = 0;

                this.feed();

                function loop(now) {
                    if (!app.macroFeedActive) {
                        app.macroFeedFrame = null;
                        return;
                    }

                    var delay =
                        Number(defaultmapsettings.macroFeeding) || 10;

                    if (delay < 1) {
                        delay = 1;
                    }

                    if (now - lastFeedTime >= delay) {
                        lastFeedTime = now;
                        app.feed();
                    }

                    app.macroFeedFrame =
                        window.requestAnimationFrame(loop);
                }

                this.macroFeedFrame =
                    window.requestAnimationFrame(loop);
            } else {
                this.macroFeedActive = false;

                if (this.macroFeedFrame != null) {
                    window.cancelAnimationFrame(
                        this.macroFeedFrame
                    );
                    this.macroFeedFrame = null;
                }

                if (this.feedInterval) {
                    clearInterval(this.feedInterval);
                    this.feedInterval = null;
                }
            }
        },
