        setSound(audioUrl) {
            if (!audioUrl || typeof audioUrl !== 'string') {
                return null;
            }
            var audioObj = new Audio();
            audioObj.crossOrigin = 'anonymous';

            if (audioUrl.startsWith('data:') || audioUrl.startsWith('blob:')) {
                audioObj.src = audioUrl;
                return audioObj;
            }

            if (window.LMSkinStorage) {
                window.LMSkinStorage.getAudio(audioUrl, function (cachedData) {
                    if (cachedData) {
                        audioObj.src = cachedData;
                    } else {
                        try {
                            fetch(audioUrl)
                                .then(function (res) { return res.blob(); })
                                .then(function (blob) {
                                    var reader = new FileReader();
                                    reader.onloadend = function () {
                                        if (reader.result) {
                                            audioObj.src = reader.result;
                                            if (window.LMSkinStorage) {
                                                window.LMSkinStorage.putAudio(audioUrl, reader.result);
                                            }
                                        }
                                    };
                                    reader.readAsDataURL(blob);
                                })
                                .catch(function () {
                                    audioObj.src = audioUrl;
                                });
                        } catch (e) {
                            audioObj.src = audioUrl;
                        }
                    }
                });
            } else {
                audioObj.src = audioUrl;
            }
            return audioObj;
        },
        /*            playSound(audio) {
                        //audio && audio.play && (audio.pause(), audio.currentTime = 0, audio.play());
                        //audio && audio.play && audio.play!==null && (audio.pause(), audio.currentTime = 0, audio.play());
                        audio.pause();
                        audio.currentTime = 0;
                        var nopromise = {
                            catch: new Function()
                        };
                        (audio.play() || nopromise).catch(function() {});
                    },
        */
        playSound(audio) {
            if (audio && audio.play) {
                audio.pause();
                audio.currentTime = 0;
                //audio.play();
                var nopromise = {
                    catch: new Function()
                };
                (audio.play() || nopromise).catch(function () { });
            }
        },
