        decompressMessage(message) {
            const buffer = window.buffer.Buffer;

            if (!message ||
                !message.buffer ||
                typeof message.byteLength !== "number") {
                throw new TypeError(
                    "Invalid compressed packet object"
                );
            }

            const messageBuffer =
                new buffer(
                    message.buffer,
                    message.byteOffset || 0,
                    message.byteLength
                );

            const MAX_COMPRESSED_PACKET_SIZE =
                8 * 1024 * 1024;

            const MAX_DECOMPRESSED_PACKET_SIZE =
                32 * 1024 * 1024;

            const MAX_COMPRESSION_RATIO =
                256;

            if (messageBuffer.length < 6) {
                throw new RangeError(
                    "Compressed packet is too short"
                );
            }

            if (messageBuffer.length >
                MAX_COMPRESSED_PACKET_SIZE) {
                throw new RangeError(
                    "Compressed packet exceeds size limit"
                );
            }

            const outputSize =
                messageBuffer.readUInt32LE(1);

            const compressedSize =
                messageBuffer.length - 5;

            if (!Number.isSafeInteger(outputSize) ||
                outputSize <= 0 ||
                outputSize >
                MAX_DECOMPRESSED_PACKET_SIZE) {
                throw new RangeError(
                    "Invalid decompressed packet size"
                );
            }

            if (compressedSize <= 0 ||
                outputSize >
                compressedSize *
                MAX_COMPRESSION_RATIO) {
                throw new RangeError(
                    "Invalid compressed packet ratio"
                );
            }

            /* ── LZ4 WASM decoder (1.3 KB inline) ── */
            if (!window._lz4wasm) {
                /* One-time async init — first packet
                 * uses JS fallback, then WASM takes over */
                if (!window._lz4wasmLoading) {
                    window._lz4wasmLoading = true;
                    var WASM_B64 = "";
                    try {
                        var bin = Uint8Array.from(
                            atob(WASM_B64),
                            function(c) {
                                return c.charCodeAt(0);
                            }
                        );
                        WebAssembly.instantiate(
                            bin.buffer, {}
                        ).then(function(result) {
                            var exp = result.instance.exports;
                            window._lz4wasm = {
                                decode: exp.lz4_decode_block,
                                srcPtr: exp.get_src_ptr(),
                                dstPtr: exp.get_dst_ptr(),
                                mem: new Uint8Array(
                                    exp.memory.buffer
                                )
                            };
                            /* LZ4 WASM init success (silent) */
                        }).catch(function(e) {
                            console.warn(
                                '[LZ4] WASM init failed, using JS fallback:', e
                            );
                        });
                    } catch (e) {
                        console.warn(
                            '[LZ4] WASM load failed:', e
                        );
                    }
                }
            }

            var src = new Uint8Array(
                message.buffer,
                (message.byteOffset || 0) + 5,
                compressedSize
            );

            /* ── Try WASM path ── */
            var wasm = window._lz4wasm;
            if (wasm &&
                compressedSize <= 262144 &&
                outputSize <= 1048576) {
                wasm.mem.set(src, wasm.srcPtr);
                var decoded = wasm.decode(
                    compressedSize, outputSize
                );
                if (decoded >= 0) {
                    var out = new Uint8Array(outputSize);
                    out.set(
                        wasm.mem.subarray(
                            wasm.dstPtr,
                            wasm.dstPtr + decoded
                        )
                    );
                    return new buffer(out.buffer);
                }
                throw new RangeError(
                    "LZ4 WASM decompression failed"
                );
            }

            /* ── JS fallback (typed arrays) ── */
            var dst = new Uint8Array(outputSize);
            var sPos = 0, dPos = 0;
            var sEnd = compressedSize;

            while (sPos < sEnd) {
                var token = src[sPos++];

                var litLen = token >>> 4;
                if (litLen === 15) {
                    var addByte;
                    do {
                        addByte = src[sPos++];
                        litLen += addByte;
                    } while (addByte === 255);
                }
                if (litLen > 0) {
                    dst.set(
                        src.subarray(sPos, sPos + litLen),
                        dPos
                    );
                    sPos += litLen;
                    dPos += litLen;
                }
                if (sPos >= sEnd) break;

                var offset =
                    src[sPos] | (src[sPos + 1] << 8);
                sPos += 2;
                if (offset === 0) {
                    throw new RangeError(
                        "LZ4: zero match offset"
                    );
                }

                var matchLen = (token & 0xF) + 4;
                if ((token & 0xF) === 15) {
                    var addByte2;
                    do {
                        addByte2 = src[sPos++];
                        matchLen += addByte2;
                    } while (addByte2 === 255);
                }

                var matchPos = dPos - offset;
                if (offset >= matchLen) {
                    dst.set(
                        dst.subarray(
                            matchPos,
                            matchPos + matchLen
                        ),
                        dPos
                    );
                    dPos += matchLen;
                } else {
                    var mEnd = dPos + matchLen;
                    while (dPos < mEnd) {
                        dst[dPos++] = dst[matchPos++];
                    }
                }
            }

            if (dPos < 0 || dPos > outputSize) {
                throw new RangeError(
                    "LZ4 decompression failed"
                );
            }
            return new buffer(dst.buffer);
        },
        /* ── Expanding Land: Handle map resize events (opcode 200) ── */
        handleMapEvent(eventType, currentSize, targetSize, centerX, centerY, transitionDur, warningDur, currentTier) {
            var me = this.mapEvent;
            if (currentTier >= 0) LM.mapTier = currentTier;
            me.currentSize = currentSize;
            me.targetSize = targetSize;
            me.startTime = Date.now();
            me.transitionDuration = transitionDur;
            me.warningDuration = warningDur;
            me.prevMinX = this.mapMinX;
            me.prevMinY = this.mapMinY;
            me.prevMaxX = this.mapMaxX;
            me.prevMaxY = this.mapMaxY;

            switch (eventType) {
                case 1: // MAP_EXPANSION_START
                    me.phase = 1;
                    me.active = true;
                    console.log('%c[LW]%c Expanding: ' + ~~currentSize + ' → ' + ~~targetSize, 'color:#3f3', 'color:inherit');
                    if (typeof toastr !== 'undefined') toastr.info('🌍 Map expanding — new territory ahead!');
                    break;
                case 2: // MAP_CONTRACTION_WARNING
                    me.phase = 2;
                    me.active = true;
                    console.log('%c[LW]%c Warning: shrink in ' + Math.round(warningDur / 25) + 's', 'color:#ff0', 'color:inherit');
                    if (typeof toastr !== 'undefined') toastr.warning('Map shrinking in ' + Math.round(warningDur / 25) + 's — move inward');
                    break;
                case 3: // MAP_CONTRACTION_DANGER
                    me.phase = 3;
                    me.active = true;
                    console.log('%c[LW]%c Danger zone active', 'color:#f33', 'color:inherit');
                    if (typeof toastr !== 'undefined') toastr.error('Danger zone — leave the red area');
                    break;
                case 4: // MAP_SHRINK_START
                    me.phase = 4;
                    me.active = true;
                    console.log('%c[LW]%c Shrinking', 'color:#f33', 'color:inherit');
                    break;
                case 5: // MAP_RESIZE_COMPLETE
                    me.phase = 0;
                    me.active = false;
                    //console.log('%c[LW]%c Resize complete: ' + ~~currentSize, 'color:#3f3', 'color:inherit');
                    break;
            }
        },
