                var cellFsSource = `#version 300 es
                precision highp float;
                precision highp sampler2DArray;

                in vec4 v_color;
                in vec2 v_unitPos;

                flat in float v_skinLayer;
                flat in float v_skinAlpha;

                uniform sampler2DArray u_skinArray;

                out vec4 fragColor;

                void main() {
                    float distSq =
                        dot(
                            v_unitPos,
                            v_unitPos
                        );

                    if (distSq > 1.0) {
                        discard;
                    }

                    float edgeAlpha =
                        1.0 -
                        smoothstep(
                            0.95,
                            1.0,
                            distSq
                        );

                    /*
                     * The body exists independently from the skin.
                     */
                    float bodyAlpha =
                        clamp(
                            v_color.a,
                            0.0,
                            1.0
                        );

                    vec3 outRgb =
                        v_color.rgb;

                    float outAlpha =
                        bodyAlpha;

                    if (
                        v_skinLayer >=
                        0.0
                    ) {
                        vec2 skinUV =
                            v_unitPos *
                            0.5 +
                            0.5;

                        vec4 skinSample =
                            texture(
                                u_skinArray,
                                vec3(
                                    skinUV,
                                    v_skinLayer
                                )
                            );

                        /*
                         * Skin transparency affects only the skin overlay.
                         * It can reveal the body, but can never erase it.
                         */
                        float skinAlpha =
                            clamp(
                                skinSample.a *
                                v_skinAlpha,
                                0.0,
                                1.0
                            );

                        /*
                         * Straight-alpha source-over composition:
                         *
                         *     skin over body
                         */
                        outAlpha =
                            skinAlpha +
                            bodyAlpha *
                            (
                                1.0 -
                                skinAlpha
                            );

                        if (
                            outAlpha >
                            0.00001
                        ) {
                            vec3 outPremultiplied =
                                skinSample.rgb *
                                skinAlpha +
                                v_color.rgb *
                                bodyAlpha *
                                (
                                    1.0 -
                                    skinAlpha
                                );

                            outRgb =
                                outPremultiplied /
                                outAlpha;
                        }
                    }

                    fragColor = vec4(
                        outRgb,
                        outAlpha *
                        edgeAlpha
                    );
                }`;

                var cellProgram = createAndLinkProgram(gl, cellVsSource, cellFsSource);
                if (!cellProgram) throw new Error('Cell WebGL program creation failed');
                this.glCellProgram = cellProgram;

                this.u_cell_viewCenter = gl.getUniformLocation(cellProgram, 'u_viewCenter');
                this.u_cell_viewScale = gl.getUniformLocation(cellProgram, 'u_viewScale');
