                    gl.enableVertexAttribArray(a_dr_col);
                    gl.vertexAttribPointer(a_dr_col, 4, gl.FLOAT, false, drStride, 3 * 4);
                    gl.vertexAttribDivisor(a_dr_col, 1);
                    gl.bindVertexArray(null);
                    this.glDashedRingData = new Float32Array(5000 * 7);
