function findOcc(arr, key) {
    let arr2 = [];

    arr.forEach((x) => {

        // Checking if there is any object in arr2
        // which contains the key value
        if (arr2.some((val) => { return val[key] === x[key] })) {

            // If yes! then increase the occurrence by 1
            arr2.forEach((k) => {
                if (k[key] === x[key]) {
                    k["occurrence"]++
                }
            })

        } else {
            // If not! Then create a new object initialize 
            // it with the present iteration key's value and 
            // set the occurrence to 1
            let a = {}
            a[key] = x[key]
            a["occurrence"] = 1
            arr2.push(a);
        }
    })

    return arr2;
    //    let key = "nick"; console.log(findOcc(legendmod.leaderboard, key));
}




Array.prototype.stDev = function stDev() {
    const average = data => data.reduce((sum, value) => sum + value) / data.length
    return Math.sqrt(average(this.map(value => Math.pow(value - average(this), 2))))
    //return Math.sqrt(average(this.map(value => (value - average(this)) ** 2)))
};

// Replace legendmod.ml URLs with jimboy3100.github.io / expanding.land equivalents.
// Uses MutationObserver so it catches dynamically created elements too.
(function () {
    var _elRewriteMap = [
        { match: /(?:www\.)?legendmod\.ml\/vanillaskins/g, replace: 'www.legendmod.ml/vanillaskins' },
        { match: /(?:www\.)?legendmod\.ml\/lowresskins/g, replace: 'www.legendmod.ml/lowresskins' },
        { match: /jimboy3000\.github\.io/g, replace: 'www.legendmod.ml' },
        { match: /jimboy3100\.github\.io/g, replace: 'www.legendmod.ml' },
        { match: /(?:www\.)?legendmod\.ml\/agario\/live\/flags/g, replace: 'www.legendmod.ml/agario/live/flags' }
    ];
    function _rewriteExpandingLinks(root) {
        (root || document).querySelectorAll('a[href*="legendmod.ml"], [src*="legendmod.ml"], [style*="legendmod.ml"]').forEach(function (el) {
            _elRewriteMap.forEach(function (r) {
                if (el.href) el.href = el.href.replace(r.match, r.replace);
                if (el.src) el.src = el.src.replace(r.match, r.replace);
                if (el.style && el.style.cssText) el.style.cssText = el.style.cssText.replace(r.match, r.replace);
            });
        });
    }
    /* Initial pass */
    _rewriteExpandingLinks();
    /* Watch for new elements added to the DOM */
    if (typeof MutationObserver !== 'undefined') {
        new MutationObserver(function (mutations) {
            mutations.forEach(function (m) {
                m.addedNodes.forEach(function (n) {
                    if (n.nodeType === 1) _rewriteExpandingLinks(n.parentElement || document);
                });
            });
        }).observe(document.documentElement, { childList: true, subtree: true });
    }

    /* Auto-load Extended UI Features Module */
    try {
        var extUiScript = document.createElement('script');
        extUiScript.type = 'text/javascript';
        extUiScript.src = 'https://www.legendmod.ml/LMexpress/lm_extended_ui.js';
        document.body.appendChild(extUiScript);
    } catch (e) {
        console.warn('[LM] Error auto-loading extended UI script:', e);
    }
})();
